def _is_mock(obj: object) -> bool:
    """
    Return True if *obj* is a ``unittest.mock`` mock object.

    Mocks answer yes to any attribute access, which makes them pass
    ``isinstance(obj, AbstractContextManager)`` and ``isawaitable(obj)``
    checks even when they are not real context managers or awaitables.
    """
    return isinstance(obj, unittest.mock.Base)


